import Ajv, {type ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly schemaValidator = new Ajv({strict: false, validateFormats: false} as never);
  private readonly validators = new WeakMap<Record<string, unknown>, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  private validatorFor(definition: ToolDefinition): ValidateFunction {
    const cached = this.validators.get(definition.inputSchema);
    if (cached) return cached;

    try {
      if (!this.schemaValidator.validateSchema(definition.inputSchema)) {
        throw new Error(this.schemaValidator.errorsText());
      }
      const validator = this.schemaValidator.compile(validationSchema(definition.inputSchema));
      this.validators.set(definition.inputSchema, validator);
      return validator;
    } catch (error) {
      const message = error instanceof Error ? error.message : 'unknown schema error';
      throw new Error(`Invalid inputSchema for tool ${definition.name}: ${message}`, {cause: error});
    }
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    if (typeof definition !== 'function') {
      this.validatorFor(resolved);
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Returns input-schema rejections; see specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const definition = this.resolveDefinition(tool.definitionSource);
    const validator = this.validatorFor(definition);
    if (!validator(input)) return {result: formatValidationErrors(validator.errors)};
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

interface ValidationError {
  keyword: string;
  instancePath?: string;
  dataPath?: string;
  schemaPath?: string;
  message?: string;
  params: object;
}

function validationSchema(schema: Record<string, unknown>): Record<string, unknown> {
  return Object.fromEntries(
    Object.entries(schema).flatMap(([keyword, value]) => {
      if (isNestedSchemaKeyword(keyword)) return nestedSchemaEntry(keyword, value);
      if (keyword === 'items') return [[keyword, projectSchema(value)]];
      if (['type', 'enum', 'required', '$ref', '$schema'].includes(keyword)) return [[keyword, value]];
      return [];
    })
  );
}

function isNestedSchemaKeyword(keyword: string): boolean {
  return ['properties', 'patternProperties', '$defs', 'definitions'].includes(keyword);
}

function nestedSchemaEntry(keyword: string, value: unknown): [string, unknown][] {
  const projected = isRecord(value)
    ? Object.fromEntries(Object.entries(value).map(([name, nested]) => [name, projectSchema(nested)]))
    : value;
  return [[keyword, projected]];
}

function projectSchema(value: unknown): unknown {
  return isRecord(value) ? validationSchema(value) : value;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function formatValidationErrors(errors: ValidationError[] | null | undefined): string {
  if (!errors?.length) return 'Tool input does not match the declared schema.';

  return errors.map(formatValidationError).join('; ');
}

function formatValidationError(error: ValidationError): string {
  if (error.keyword === 'required') {
    return `${joinInstancePath(requiredPropertyParentPath(error), validationParameter(error, 'missingProperty'))} is required.`;
  }
  if (error.keyword === 'type') {
    return `${errorPath(error)} must be a ${String(validationParameter(error, 'type'))}.`;
  }
  if (error.keyword === 'enum') {
    return `${errorPath(error)} must match an allowed value.`;
  }
  return `${error.instancePath || '/'} ${error.message ?? 'does not match the declared schema'}.`;
}

function errorPath(error: ValidationError): string {
  return normalizeInstancePath(error.instancePath || error.dataPath) || '/';
}

function validationParameter(error: ValidationError, parameter: string): unknown {
  return (error.params as Record<string, unknown>)[parameter];
}

function joinInstancePath(instancePath: string | undefined, property: unknown): string {
  return `${instancePath || ''}/${String(property)}`;
}

function requiredPropertyParentPath(error: ValidationError): string | undefined {
  return normalizeInstancePath(error.instancePath || error.dataPath) || parentPathFromSchemaPath(error.schemaPath);
}

function normalizeInstancePath(path: string | undefined): string | undefined {
  if (!path || path.startsWith('/')) return path;
  return path.replaceAll('.', '/');
}

function parentPathFromSchemaPath(schemaPath: string | undefined): string | undefined {
  if (!schemaPath) return undefined;

  const propertySegments = schemaPath
    .split('/')
    .slice(1, -1)
    .filter(segment => segment !== 'properties');
  return propertySegments.length ? `/${propertySegments.join('/')}` : undefined;
}
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | In Progress          |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

## Validation at execute time

- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required and never invokes the executor ([validated by: rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L21)).
- A rejection for a nested missing required property identifies its complete JSON Pointer path as well as the required constraint ([validated by: names the complete path for a nested missing required property](../../src/orchestration/tools/registry.test.ts#L166); [validated by: formats legacy nested required paths as JSON Pointers](../../src/orchestration/tools/registry.test.ts#L174)).
- A nested object with several missing required properties retains that object's JSON Pointer prefix in every rejection path, including validators that report legacy dotted `dataPath` values ([validated by: normalizes a legacy dotted dataPath in a required-property rejection](../../src/orchestration/tools/registry.test.ts#L205)).
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, and neither `result` nor the emitted log record contains the offending property value ([validated by: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L51); [validated by: rejects a wrong-typed input without revealing its value](../../src/orchestration/tools/registry.test.ts#L132)).
- A rejection for a property that does not match its declared `enum` identifies that property's JSON Pointer path, including validators that report legacy dotted `dataPath` values ([validated by: formats legacy enum paths as JSON Pointers](../../src/orchestration/tools/registry.test.ts#L182)).
- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults ([validated by: passes valid input with undeclared properties through unchanged exactly once](../../src/orchestration/tools/registry.test.ts#L48)).
- Validation limits its constraints to `required`, declared property types, and `enum`; a numeric lower bound in a tool schema does not prevent an otherwise type-valid input from reaching the executor ([validated by: passes a type-valid value that is below an unvalidated numeric bound to the executor](../../src/orchestration/tools/registry.test.ts#L76)).
- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake ([validated by: throws for an unregistered tool name](../../src/orchestration/tools/registry.test.ts#L42)).

## Schema compilation and caching

- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by: throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L99)).
- A static schema with an invalid constraint is rejected at registration even when that constraint is outside the runtime validation subset ([validated by: rejects an invalid ignored constraint at registration](../../src/orchestration/tools/registry.test.ts#L27)).
- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema` ([validated by: compiles a static schema once across repeated executions](../../src/orchestration/tools/registry.test.ts#L228)).
- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules ([validated by: uses the current schema from a function-valued definition source](../../src/orchestration/tools/registry.test.ts#L100)).

## Orchestrator tool-loop recovery

- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by: returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round](../../src/orchestration/tools/registry.acceptance.test.ts#L117)).
